def main() -> None:
    mode = sys.argv[1] if len(sys.argv) > 1 else "--emit-manifest"
    if mode == "--emit-spoken":
        for name, voice, _tags, spoken, _expected in SET:
            print(f"{name}|{voice}|{spoken}")
        return
    fixtures = [
        {"audio": f"audio/{name}.wav", "expected": expected, "tags": ["synthetic"] + tags}
        for name, _voice, tags, _spoken, expected in SET
    ]
    print(json.dumps({"fixtures": fixtures}, ensure_ascii=False, indent=2))


if __name__ == "__main__":
    main()
